<?php

declare(strict_types=1);
require_once __DIR__ . '/../includes/bootstrap.php';
require_role('ADMIN');
if (is_post()) {
    verify_csrf_or_abort();
    $action=(string)($_POST['action']??'');
    $result=$action==='refund' ? admin_refund_payment((int)($_POST['payment_id']??0),trim((string)($_POST['note']??''))) : ['ok'=>false,'message'=>'Choose a valid payment action.'];
    flash($result['ok']?'success':'error',$result['message']); redirect('admin/payments.php');
}
$q=trim((string)($_GET['q']??''));$status=strtoupper(trim((string)($_GET['status']??'ALL')));$method=strtoupper(trim((string)($_GET['method']??'ALL')));
$payments=admin_payments(compact('q','status','method'));$metrics=admin_payment_metrics();$methods=db()->query('SELECT code,name FROM payment_methods ORDER BY id')->fetchAll();
$pageTitle='Payments';$bodyClass='portal-page';require __DIR__.'/../includes/header.php';$success=flash('success');$error=flash('error');
?>
<div class="portal-shell"><?php require __DIR__.'/../includes/sidebar.php'; ?><main class="portal-main"><header class="portal-page-header"><div><span class="eyebrow">FINANCE</span><h1 class="mt-2 mb-1">Payments</h1><p class="text-muted mb-0">Review all cash, GCash, Maya, pickup, and delivery payments in one ledger.</p></div></header>
<?php if($success):?><div class="alert alert-success"><?=e($success)?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?>
<section class="finance-metrics"><div><span>Transactions</span><strong><?=$metrics['total']?></strong></div><div><span>Pending</span><strong><?=$metrics['pending']?></strong></div><div><span>Paid value</span><strong><?=money($metrics['paid_amount'])?></strong></div><div><span>Refunded</span><strong><?=$metrics['refunded']?></strong></div></section>
<section class="portal-card inventory-filter-card"><form method="get" class="finance-filter-grid"><div><label class="form-label">Search</label><input class="form-control" name="q" value="<?=e($q)?>" placeholder="Payment, order, customer, reference"></div><div><label class="form-label">Status</label><select class="form-select" name="status"><?php foreach(['ALL','UNPAID','PENDING','PAID','FAILED','REFUNDED'] as $s):?><option value="<?=$s?>" <?=$status===$s?'selected':''?>><?=$s?></option><?php endforeach;?></select></div><div><label class="form-label">Method</label><select class="form-select" name="method"><option value="ALL">All methods</option><?php foreach($methods as $m):?><option value="<?=e($m['code'])?>" <?=$method===$m['code']?'selected':''?>><?=e($m['name'])?></option><?php endforeach;?></select></div><div class="inventory-filter-actions"><button class="btn btn-coffee">Apply</button><a class="btn btn-outline-secondary" href="<?=url('admin/payments.php')?>">Reset</a></div></form></section>
<section class="portal-card mt-4"><div class="panel-heading"><div><span class="eyebrow">PAYMENT LEDGER</span><h2><?=count($payments)?> result<?=count($payments)===1?'':'s'?></h2></div></div><?php if(!$payments):?><div class="empty-state compact"><i class="bi bi-credit-card"></i><h3>No payments found</h3><p>Try a different filter.</p></div><?php else:?><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Payment</th><th>Order / Customer</th><th>Method</th><th>Amount</th><th>Status</th><th>Reference</th><th>Verified</th><th class="text-end">Actions</th></tr></thead><tbody><?php foreach($payments as $p):?><tr><td><strong><?=e($p['payment_number'])?></strong><small class="d-block text-muted"><?=e(date('M j, Y g:i A',strtotime($p['created_at'])))?></small></td><td><strong><?=e($p['order_number'])?></strong><small class="d-block text-muted"><?=e($p['contact_name']?:'Walk-in')?> · <?=e($p['order_source'])?></small></td><td><?=e($p['method_name'])?></td><td><strong><?=money((float)$p['amount'])?></strong></td><td><span class="badge <?=match($p['status']){'PAID'=>'text-bg-success','PENDING'=>'text-bg-warning','FAILED'=>'text-bg-danger','REFUNDED'=>'text-bg-secondary',default=>'text-bg-light'}?>"><?=e($p['status'])?></span></td><td><?=e($p['reference_number']?:'—')?></td><td><?=!empty($p['verified_at'])?e(trim(($p['verifier_first']??'').' '.($p['verifier_last']??''))):'—'?></td><td class="text-end"><div class="catalog-action-group"><a class="btn btn-sm btn-outline-coffee" href="<?=url('staff/order-details.php?order='.rawurlencode($p['order_number']))?>">View order</a><?php if($p['status']==='PAID'):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="refund"><input type="hidden" name="payment_id" value="<?=(int)$p['id']?>"><input type="hidden" name="note" value="Refund recorded from Finance"><button class="btn btn-sm btn-outline-danger" data-confirm="Mark this payment as refunded? This records the refund status but does not automatically cancel the order.">Refund</button></form><?php endif;?></div></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>
</main></div><?php require __DIR__.'/../includes/footer.php'; ?>
